//! 🧪️ Genuine resident Arc acquisition and release keep original Work and physical custody.
use semio_framework_value_allocation_return::*;
use std::{sync::Arc,mem::MaybeUninit};
use semio_framework_value_control_contract::{RetainedCloneGrant,RetainedCloneProgress,ValueError,ValueRefusalKind};
use semio_framework_value_testing_allocator::{observe_retirement_allocations as observe,refuse_one_allocation_on_this_thread as refuse};

#[test]
fn resident_uninitialized_arc_uses_its_actual_source_receipt_and_keeps_denied_output(){
 use semio_framework_value_testing_effect_bank::{EffectBank,Wallet,RetainedWorkPoll};
 let law:serde_json::Value=serde_json::from_str(include_str!("resident-arc.json")).unwrap();
 for axis in law["denied"].as_array().unwrap(){
  let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut output=None;let demand=shared_uninitialized_demand::<u64>().unwrap();let mut grant=bank.loan(1,demand.copy_bytes);let mut maximum=shared_uninitialized_work_demand();match axis.as_str().unwrap(){"items"=>grant.maximum_items=0,"copy"=>grant.maximum_copy_bytes-=1,"capacity"=>grant.maximum_capacity_bytes=demand.capacity_bytes-1,"depth"=>grant.maximum_depth=0,"work"=>maximum=0,_=>{}}
  let spent=u64::from(axis=="spent");let((poll,marker),heap)=observe(||bank.run(grant,maximum,|effect|{if spent!=0{assert!(effect.performed(spent).unwrap())}let turn=try_uninitialized_arc_into::<u64>(&mut output,effect);assert_eq!(turn.work,0);RetainedWorkPoll::Complete(RetainedWorkOutcome{result:turn.result,work:u128::from(spent)})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("native shared primitive unexpectedly pending")};assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(marker,None);assert_eq!(heap,(0,0));assert!(output.is_none());assert_eq!(bank.take_admitted(),(spent!=0).then_some(true));bank.post(Default::default(),grant,heap)
 }
}
#[test]
fn resident_uninitialized_arc_records_null_and_physical_release_without_reconstructing_work(){
 use semio_framework_value_testing_effect_bank::{EffectBank,Wallet,RetainedWorkPoll};
 let law:serde_json::Value=serde_json::from_str(include_str!("resident-arc.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut output=None;
 for null in [true,false]{let demand=shared_uninitialized_demand::<u64>().unwrap();let grant=bank.loan(1,demand.copy_bytes);let((poll,marker),heap)=observe(||bank.run(grant,shared_uninitialized_work_demand(),|effect|{let turn=if null{let(turn,attempts)=refuse(||try_uninitialized_arc_into::<u64>(&mut output,effect));assert_eq!(attempts,1);turn}else{try_uninitialized_arc_into::<u64>(&mut output,effect)};RetainedWorkPoll::Complete(turn)}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("native shared primitive unexpectedly pending")};assert_eq!(turn.work,u128::from(law["allocation"]["work"].as_u64().unwrap()));assert_eq!(bank.take_admitted(),Some(true));let progress=if null{let error=turn.result.unwrap_err();assert_eq!(error.kind,ValueRefusalKind::AllocationFailed);assert_eq!(marker,Some(0));assert!(output.is_none());error.retained_progress()}else{assert!(output.is_some());assert_eq!(marker,Some(demand.capacity_bytes));let progress=turn.result.unwrap().progress();assert_eq!(progress.copied_bytes,demand.copy_bytes);progress};bank.post(progress,grant,heap)}
 let pointer=Arc::as_ptr(output.as_ref().unwrap());let demand=uninitialized_arc_release_demand(&output);let grant=bank.loan(1,demand.copy_bytes);let denied=RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..grant};let((poll,marker),heap)=observe(||bank.run(denied,1,|effect|RetainedWorkPoll::Complete(release_uninitialized_arc_from(&mut output,effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("native shared release unexpectedly pending")};assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(Arc::as_ptr(output.as_ref().unwrap()),pointer);assert_eq!(marker,None);assert_eq!(bank.take_admitted(),None);bank.post(Default::default(),denied,heap);
 let grant=bank.loan(1,demand.copy_bytes);let((poll,marker),heap)=observe(||bank.run(grant,1,|effect|RetainedWorkPoll::Complete(release_uninitialized_arc_from(&mut output,effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("native shared release unexpectedly pending")};assert_eq!(turn.work,1);assert_eq!(bank.take_admitted(),Some(true));assert_eq!(marker,None);assert!(output.is_none());bank.post(turn.result.unwrap().progress(),grant,heap);
}

#[test]
fn resident_arc_publication_preserves_the_original_payload_and_pays_its_same_work(){
 use semio_framework_value_testing_effect_bank::{EffectBank,Wallet,RetainedWorkPoll};
 let law:serde_json::Value=serde_json::from_str(include_str!("resident-arc.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let expected:u64=serde_json::from_value(law["publication"]["value"].clone()).unwrap();let mut input=Some(expected);let mut birth=None;let mut output=None;let d=shared_uninitialized_demand::<u64>().unwrap();let g=bank.loan(1,d.copy_bytes);let((poll,marker),heap)=observe(||bank.run(g,1,|effect|RetainedWorkPoll::Complete(try_uninitialized_arc_into(&mut birth,effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("allocation remained pending")};assert_eq!(marker,Some(d.capacity_bytes));assert_eq!(bank.take_admitted(),Some(true));bank.post(turn.result.unwrap().progress(),g,heap);let pointer=Arc::as_ptr(birth.as_ref().unwrap());let d=shared_arc_publication_demand::<u64>().unwrap();
 for denied in [true,false]{let g=bank.loan(1,d.copy_bytes);let g=if denied{RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g}}else{g};let((poll,marker),heap)=observe(||bank.run(g,shared_arc_publication_work_demand(),|effect|RetainedWorkPoll::Complete(publish_uninitialized_arc_from(&mut birth,&mut input,&mut output,effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("publication remained pending")};assert_eq!(marker,None);assert_eq!(heap,(0,0));if denied{assert_eq!(turn.work,0);assert_eq!(input,Some(expected));assert!(output.is_none());assert_eq!(Arc::as_ptr(birth.as_ref().unwrap()),pointer);assert_eq!(bank.take_admitted(),None)}else{assert_eq!(turn.work,u128::from(law["publication"]["work"].as_u64().unwrap()));assert!(input.is_none()&&birth.is_none());assert_eq!(Arc::as_ptr(output.as_ref().unwrap()).cast::<MaybeUninit<u64>>(),pointer);assert_eq!(serde_json::to_value(**output.as_ref().unwrap()).unwrap(),law["publication"]["value"]);assert_eq!(bank.take_admitted(),Some(true))}bank.post(turn.result.unwrap().progress(),g,heap)}
 let d=RetirementDemand{copy_bytes:size_of::<Option<Arc<u64>>>()+2*size_of::<usize>(),release_bytes:shared_allocation_bytes::<u64>(),depth:1,..Default::default()};let g=bank.loan(1,d.copy_bytes);let((poll,marker),heap)=observe(||bank.run(g,1,|effect|{assert!(effect.performed(1).unwrap());drop(output.take());RetainedWorkPoll::<RetainedCloneStep,ValueError>::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()})),work:1})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("fixture consumer release remained pending")};assert_eq!(marker,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(turn.result.unwrap().progress(),g,heap)
}
